t.transferFrom(msg.sender,address(this),amount); credit[msg.sender]+=amount; } }

pragma solidity 0.8.24;
interface Token { function transferFrom(address,address,uint) external returns(bool); } contract Deposits { Token immutable t; mapping(address=>uint) public credit; constructor(Token x){t=x;} function deposit(uint amount) external { // Token is non-reentrant, has no transfer fee and returns true exactly when amount was transferred.
require(t.transferFrom(msg.sender,address(this),amount)); credit[msg.sender]+=amount; } }

